async function collectionCall(body){$('#save-state').textContent='Saving record…';const response=await fetch('/api/collection',{method:'POST',headers:{'Content-Type':'application/json','X-Proof-Delay-Ms':String(delay)},body:JSON.stringify(body)});const result=await response.json();if(!response.ok){const error=Error(/^(compile|publish|parse) /.test(result.error||'')?'The native definition could not compile. Your fields and draft are kept.':result.error||'Native collection check failed');error.detail=result.error;throw error;}nativeState=result.frame;if(!undoing)undoStack.push(body.action==='update'&&body.before&&Object.keys(body.before).length?{kind:'nativepatch',reason:'Edit record',collection:body.collection,record:body.record,component:body.component,before:clone(body.before),after:Object.fromEntries(Object.keys(body.before).map(k=>[k,String(body.values[k])]))}:{kind:'native',reason:body.action==='create'?'Create collection':body.action==='record'?'Add record':'Edit record',expected:nativeState.expected});renderData();return result;}
