function renderScreen(){const host=$('#screen-data');host.replaceChildren();for(const b of active()){const card=element('div',undefined,'ns-card screen-card'),heading=element('div',undefined,'ns-title'),name=element('b',title(b));name.title=b.id;name.draggable=true;name.ondragstart=e=>e.dataTransfer.setData('application/grove-screen',b.id);name.onclick=()=>{if(pointing){bindScreen(byId(pointing),b.id);pointing=null;}else{select(b.id);reveal(b);}};heading.append(name,element('small',b.shape||b.part));card.append(heading);const chips=element('div',undefined,'field-chips');const keys=b.part==='shape'?['width','height','fill']:['selection',...(fields(b).length?['items']:[])];for(const key of keys){const chip=element('button',key,'field-chip');chip.draggable=true;chip.ondragstart=e=>{e.stopPropagation();e.dataTransfer.setData('application/grove-field',JSON.stringify({sourceId:b.id,property:key}));};chips.append(chip);}card.append(chips);host.append(card);}}
function bindCollection(b,id){if(!b||!nativeNode(id))return;if(b.part==='form'){const root=createForm(id,null,b.rect);b.archived=true;save(b);render();return root;}if(b.part==='dial'){b.properties=dialBindings(nativeNode(id).properties);b.mapping=Object.fromEntries(Object.entries(b.properties).map(([k,p])=>[k,p.field]));}if(b.part==='board'&&!b.groupField){const fields=nativeNode(id).properties;const exact=fields.filter(f=>f.role==='group'&&['Enum','Ref'].includes(f.type));if(exact.length===1)b.groupField=exact[0].label;}checkpoint('Bind source');b.nativeCollection=id;b.sourceId=null;save(b);render();showProperties();log(title(b)+' ← '+nativeName(id),'local','Explicit native binding');}
