 const b=byId(selected);if(!b)return;
 if(maker){renderMaker();return;}
 $('#detail-title').textContent=title(b);$('#decision-candidates').replaceChildren();$('#contract-card').replaceChildren();
 for(const [key,value]of [['SOURCE',collection(b)?nativeName(collection(b)):'? drop native material'],['READS',Object.entries(b.mapping||{}).map(([k,v])=>k+' ← '+v).join(' · ')||'—'],['WRITES',Object.entries(b.properties||{}).filter(([,p])=>p.mode==='input').map(([k,p])=>k+' → '+(p.field||'? destination')).join(' · ')||'—']]){const row=element('div',undefined,'contract-row');row.append(element('b',key),element('span',value));$('#contract-card').append(row);}
