function positionPopover(b){const pop=$('#property-popover');const x=b.rect.x*zoom,y=(b.rect.y+b.rect.h)*zoom+12;const left=Math.max(viewport.scrollLeft+8,Math.min(x,viewport.scrollLeft+viewport.clientWidth-328));const top=Math.max(viewport.scrollTop+8,Math.min(y,viewport.scrollTop+viewport.clientHeight-pop.offsetHeight-8));pop.style.left=left+'px';pop.style.top=top+'px';}
function pointAt(event){const bounds=scene.getBoundingClientRect();return{x:(event.clientX-bounds.left)/zoom,y:(event.clientY-bounds.top)/zoom};}
function snapPosition(b,x,y){const out={x:Math.max(0,Math.round(x/10)*10),y:Math.max(0,Math.round(y/10)*10)};for(const axis of ['x','y']){const size=axis==='x'?'w':'h';let nearest=6,line=null;for(const other of active()){if(other.id===b.id||ancestorIds(other).includes(b.id))continue;for(const target of [other.rect[axis],other.rect[axis]+other.rect[size]/2,other.rect[axis]+other.rect[size]])for(const offset of [0,b.rect[size]/2,b.rect[size]]){const distance=Math.abs((axis==='x'?x:y)+offset-target);if(distance<nearest){nearest=distance;out[axis]=Math.max(0,target-offset);line=target;}}}const guide=$('#guide-'+axis);guide.hidden=line===null;if(line!==null)guide.style[axis==='x'?'left':'top']=line+'px';}return out;}
